```csharp
using System;
using System.Threading.Tasks;
using Xunit;
using OpenRA.Mods.Common.Server;
using OpenRA.Server;

namespace OpenRA.Mods.Common.Tests.Server
{
	// Minimal fake implementations to allow testing MasterServerPinger.Tick
	class FakeServer : Server
	{
		public override bool IsMultiplayer => true;
		public override ServerSettings Settings { get; } = new ServerSettings
		{
			AdvertiseOnline = true,
			AdvertiseOnLocalNetwork = false
		};

		public override ModData ModData { get; } = new FakeModData();

		public override void SendFluentMessage(string message)
		{
			// No-op
		}
	}

	class FakeModData : ModData
	{
		public override T GetOrCreate<T>() where T : new()
		{
			if (typeof(T) == typeof(WebServices))
				return (T)(object)new WebServices { ServerAdvertise = "http://localhost" };
			return base.GetOrCreate<T>();
		}
	}

	public class MasterServerPingerTests
	{
		[Fact]
		public void Tick_DoesNotThrow()
		{
			var pinger = new MasterServerPinger();
			var server = new FakeServer();

			// Call Tick which triggers UpdateMasterServer and the PostAsync call internally
			pinger.Tick(server);

			// No exception means the code path was exercised
			Assert.True(true);
		}
	}
}
